{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Fisetin, the closest structural analogue (Morgan 0.42), shows poor oral bioavailability in humans; its phenolic benzopyrone core and first-pass metabolism support a low-F pattern for the query, despite fisetin having more phenolic groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Chrysin, a dihydroxyflavone, has an estimated absolute oral bioavailability of only 0.003–0.02% in humans after a 400 mg oral dose, demonstrating that phenolic benzopyrones can undergo near-complete first-pass conjugation and fail the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Quercetin absolute oral bioavailability was 0.15 ± 0.01% in healthy adults, reinforcing that polyphenolic benzopyrones generally have very low systemic F; the query's single phenol remains a UGT substrate but the same metabolic liability applies.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Gallium maltolate, a small hydroxypyrone complex, gives high oral gallium bioavailability (25–57%) in humans, a contradictory signal that small pyrone-like molecules can be absorbed; however, the measurement is for gallium, not the organic ligand, so applicability to the query is limited.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a 7-hydroxy-4-methylcoumarin. Although its small size and lipophilicity favor absorption, the consistent experimental evidence from structurally related phenolic benzopyrones (fisetin, chrysin, quercetin) shows very low oral bioavailability in humans due to extensive first-pass conjugation and poor systemic parent exposure. The single phenol is a known UGT substrate, and the coumarin core does not provide a clear escape from this liability. The only high-bioavailability analogue measures gallium absorption from a maltol complex, not the organic molecule, so it is weakly contradictory. Overall, F <20% is better supported.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for 4-methylumbelliferone itself.",
    "The closest analogues are flavonoids with multiple phenolic groups, so the degree of first-pass conjugation may be lower for the query's single phenol.",
    "No coumarin-specific oral bioavailability evidence is available in the provided set.",
    "Gallium maltolate evidence reports metal bioavailability rather than the organic ligand's F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

